import frappe
from frappe import _
def execute(filters=None):
    f=frappe._dict(filters or {});conditions=["cl.company=%s"];values=[f.company]
    if f.budget_period:
        conditions.append("%s in (coalesce(ce.commitment_period,''),coalesce(ce.actual_period,''),coalesce(ce.adjustment_period,''),coalesce(ce.origin_period,''))");values.append(f.budget_period)
    conditions.append("(coalesce(ce.commitment_period,'')!=coalesce(ce.actual_period,'') or coalesce(ce.adjustment_period,'')!='' or coalesce(ce.carry_forward_key,'')!='')")
    rows=frappe.db.sql("select ce.parent ledger,ce.reference_doctype,ce.reference_name,ce.project,ce.budget_line,ce.stage,ce.direction,ce.base_amount,ce.commitment_period,ce.actual_period,ce.adjustment_period,ce.origin_period,ce.carry_forward_from,ce.carry_forward_key,ce.carry_forward_batch from `tabCommitment Entry` ce inner join `tabCommitment Ledger` cl on cl.name=ce.parent where "+" and ".join(conditions)+" order by ce.posting_date,ce.creation",tuple(values),as_dict=True)
    columns=[{"label":_("Ledger"),"fieldname":"ledger","fieldtype":"Link","options":"Commitment Ledger","width":170,"sticky":True},{"label":_("Source"),"fieldname":"reference_name","fieldtype":"Dynamic Link","options":"reference_doctype","width":170,"sticky":True},{"label":_("Project"),"fieldname":"project","fieldtype":"Link","options":"Project","width":160},{"label":_("Budget Line"),"fieldname":"budget_line","fieldtype":"Link","options":"Budget Line","width":220},{"label":_("Stage"),"fieldname":"stage","width":100},{"label":_("Direction"),"fieldname":"direction","width":90},{"label":_("Amount"),"fieldname":"base_amount","fieldtype":"Currency","width":120},{"label":_("Commitment Period"),"fieldname":"commitment_period","fieldtype":"Link","options":"Budget Period","width":150},{"label":_("Actual Period"),"fieldname":"actual_period","fieldtype":"Link","options":"Budget Period","width":150},{"label":_("Adjustment Period"),"fieldname":"adjustment_period","fieldtype":"Link","options":"Budget Period","width":150},{"label":_("Origin Period"),"fieldname":"origin_period","fieldtype":"Link","options":"Budget Period","width":150},{"label":_("Carry Forward Batch"),"fieldname":"carry_forward_batch","width":180}]
    return columns,rows
